// SMS send gate for appointment reminders.
// The scheduler calls checkSms(user, now) before handing a text to the SMS vendor.
// Pure function: no state, no network, no reliance on the machine's time zone.

// Texts may go out only between 08:00 (inclusive) and 21:00 (exclusive),
// on the patient's own local clock. This matches the US federal TCPA window.
const SEND_START_HOUR = 8;
const SEND_END_HOUR = 21;

const formatters = new Map();

// Returns a formatter for the zone, or null if the zone is not a valid IANA name.
function getFormatter(timeZone) {
  if (typeof timeZone !== 'string' || timeZone.trim() === '') return null;
  if (formatters.has(timeZone)) return formatters.get(timeZone);
  let formatter;
  try {
    formatter = new Intl.DateTimeFormat('en-US', {
      timeZone,
      hourCycle: 'h23',
      year: 'numeric',
      month: 'numeric',
      day: 'numeric',
      hour: 'numeric',
      minute: 'numeric',
      second: 'numeric',
    });
  } catch {
    return null;
  }
  formatters.set(timeZone, formatter);
  return formatter;
}

// Wall-clock fields of an instant as seen in the zone.
function localFields(instant, formatter) {
  const parts = {};
  for (const { type, value } of formatter.formatToParts(instant)) {
    parts[type] = Number(value);
  }
  return {
    year: parts.year,
    month: parts.month,
    day: parts.day,
    hour: parts.hour,
    minute: parts.minute,
    second: parts.second,
  };
}

// Offset in ms between the zone's wall clock and UTC at this instant.
function offsetAt(instant, formatter) {
  const f = localFields(instant, formatter);
  const asUtc = Date.UTC(f.year, f.month - 1, f.day, f.hour, f.minute, f.second);
  return asUtc - Math.floor(instant.getTime() / 1000) * 1000;
}

// The instant at which the zone's wall clock reads year-month-day hour:00.
// Corrects for the offset in force at the target moment, so DST and
// half-hour zones both resolve to the right instant.
function wallClockToInstant(year, month, day, hour, formatter) {
  const guess = Date.UTC(year, month - 1, day, hour, 0, 0);
  const firstOffset = offsetAt(new Date(guess), formatter);
  let result = guess - firstOffset;
  const secondOffset = offsetAt(new Date(result), formatter);
  if (secondOffset !== firstOffset) {
    result = guess - secondOffset;
  }
  return new Date(result);
}

function pad(n) {
  return String(n).padStart(2, '0');
}

export function checkSms(user, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    return {
      allowed: false,
      reason: 'Held: the current time is invalid, so quiet hours cannot be checked.',
      nextAllowedAt: null,
    };
  }

  const timeZone = user?.timezone;
  const formatter = getFormatter(timeZone);
  if (!formatter) {
    // Without a valid zone we cannot know the patient's local clock, and we
    // cannot predict when they will set one, so there is no retry time.
    return {
      allowed: false,
      reason: 'Held: the patient has no valid time zone on file, so their local quiet hours cannot be checked.',
      nextAllowedAt: null,
    };
  }

  const local = localFields(now, formatter);
  const clock = `${pad(local.hour)}:${pad(local.minute)}`;

  if (local.hour >= SEND_START_HOUR && local.hour < SEND_END_HOUR) {
    return {
      allowed: true,
      reason: `Within ${pad(SEND_START_HOUR)}:00–${pad(SEND_END_HOUR)}:00 local time (it is ${clock} in ${timeZone}).`,
      nextAllowedAt: null,
    };
  }

  const window = `${pad(SEND_START_HOUR)}:00 to ${pad(SEND_END_HOUR)}:00`;

  if (local.hour < SEND_START_HOUR) {
    // Too early: the next window opens later today.
    const nextAllowedAt = wallClockToInstant(
      local.year, local.month, local.day, SEND_START_HOUR, formatter,
    );
    return {
      allowed: false,
      reason: `Held: it is ${clock} in ${timeZone}; reminders go out only from ${window} local time.`,
      nextAllowedAt,
    };
  }

  // Too late: the next window opens at 08:00 on the next calendar day.
  // Date.UTC does the calendar arithmetic (month and year rollover) on plain Y-M-D.
  const tomorrow = new Date(Date.UTC(local.year, local.month - 1, local.day + 1));
  const nextAllowedAt = wallClockToInstant(
    tomorrow.getUTCFullYear(),
    tomorrow.getUTCMonth() + 1,
    tomorrow.getUTCDate(),
    SEND_START_HOUR,
    formatter,
  );
  return {
    allowed: false,
    reason: `Held: it is ${clock} in ${timeZone}; reminders go out only from ${window} local time.`,
    nextAllowedAt,
  };
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { checkSms } from './bot.mjs';

const chicago = { id: 'u_1', phone: '+13125550142', timezone: 'America/Chicago' };
const at = (iso) => new Date(iso);

test('allowed inside the window, nextAllowedAt is null', () => {
  // 13:00 CDT (UTC-5 in late October)
  const r = checkSms(chicago, at('2026-10-23T18:00:00Z'));
  assert.equal(r.allowed, true);
  assert.equal(r.nextAllowedAt, null);
  assert.equal(typeof r.reason, 'string');
});

test('08:00 local is the first allowed moment, 07:59:59 is held', () => {
  assert.equal(checkSms(chicago, at('2026-10-23T13:00:00Z')).allowed, true);
  const early = checkSms(chicago, at('2026-10-23T12:59:59Z'));
  assert.equal(early.allowed, false);
  assert.equal(early.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');
});

test('before 08:00 local: retry at 08:00 the same local day', () => {
  // 06:30 CDT
  const now = at('2026-10-23T11:30:00Z');
  const r = checkSms(chicago, now);
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T13:00:00.000Z');
  assert.match(r.reason, /06:30/);
});

test('20:59:59 local is allowed, 21:00 local is held until 08:00 next day', () => {
  assert.equal(checkSms(chicago, at('2026-10-24T01:59:59Z')).allowed, true);
  const late = checkSms(chicago, at('2026-10-24T02:00:00Z'));
  assert.equal(late.allowed, false);
  assert.equal(late.nextAllowedAt.toISOString(), '2026-10-24T13:00:00.000Z');
});

test('late evening across month end rolls to the next month', () => {
  const tz = { timezone: 'America/Chicago' };
  // 2026-10-31 22:00 CDT = 2026-11-01 03:00Z
  const r = checkSms(tz, at('2026-11-01T03:00:00Z'));
  assert.equal(r.allowed, false);
  // Nov 1 2026 is still CDT, so 08:00 CDT is 13:00Z
  assert.equal(r.nextAllowedAt.toISOString(), '2026-11-01T13:00:00.000Z');
});

test('half-hour zone (Asia/Kolkata, UTC+5:30)', () => {
  const user = { timezone: 'Asia/Kolkata' };
  // 07:50 IST = 02:20Z
  const r = checkSms(user, at('2026-10-23T02:20:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T02:30:00.000Z');
  assert.equal(checkSms(user, r.nextAllowedAt).allowed, true);
  assert.equal(checkSms(user, new Date(r.nextAllowedAt - 1)).allowed, false);
});

test('DST spring-forward day uses the real offset, not a fixed one', () => {
  // New York springs forward 2026-03-08 at 02:00 EST. 07:30 EDT = 11:30Z.
  const ny = { timezone: 'America/New_York' };
  const r = checkSms(ny, at('2026-03-08T11:30:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt.toISOString(), '2026-03-08T12:00:00.000Z');
});

test('the machine time zone does not matter', () => {
  const user = { timezone: 'Pacific/Honolulu' };
  // 2026-10-23 06:00Z = 20:00 HST (UTC-10), allowed; 2026-10-23 18:00Z = 08:00 HST, allowed.
  assert.equal(checkSms(user, at('2026-10-23T06:00:00Z')).allowed, true);
  const r = checkSms(user, at('2026-10-23T17:00:00Z')); // 07:00 HST
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt.toISOString(), '2026-10-23T18:00:00.000Z');
});

test('missing timezone is held with no retry time', () => {
  for (const tz of [null, undefined, '', 'Mars/Olympus', 'not a zone', 42]) {
    const r = checkSms({ id: 'u', phone: '+1', timezone: tz }, at('2026-10-23T18:00:00Z'));
    assert.equal(r.allowed, false, `timezone ${String(tz)}`);
    assert.equal(r.nextAllowedAt, null, `timezone ${String(tz)}`);
    assert.match(r.reason, /no valid time zone/);
  }
});

test('invalid now is held', () => {
  const r = checkSms(chicago, new Date('nope'));
  assert.equal(r.allowed, false);
  assert.equal(r.nextAllowedAt, null);
});

test('reason strings are sentences a support person can read', () => {
  const r = checkSms(chicago, at('2026-10-23T11:30:00Z'));
  assert.equal(
    r.reason,
    'Held: it is 06:30 in America/Chicago; reminders go out only from 08:00 to 21:00 local time.',
  );
});

