import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g1-2/bot.mjs';
const zones = ['America/Chicago','America/New_York','Asia/Kolkata','Australia/Lord_Howe','Pacific/Chatham','Pacific/Honolulu','America/St_Johns'];
let checked = 0, bad = 0;
const start = Date.UTC(2026, 0, 1), end = Date.UTC(2027, 0, 1);
for (const tz of zones) {
  for (let t = start; t < end; t += 15 * 60 * 1000) {
    const now = new Date(t);
    const r = checkSms({ timezone: tz }, now);
    checked++;
    if (r.allowed) { if (r.nextAllowedAt !== null) { bad++; console.log('allowed but next set', tz, now); } continue; }
    const n = r.nextAllowedAt;
    if (!(n instanceof Date) || n <= now) { bad++; console.log('bad next', tz, now.toISOString()); continue; }
    const atNext = checkSms({ timezone: tz }, n);
    const justBefore = checkSms({ timezone: tz }, new Date(n - 1000));
    if (!atNext.allowed || justBefore.allowed) { bad++; if (bad < 10) console.log('not exact', tz, now.toISOString(), n.toISOString()); }
  }
}
console.log({ checked, bad });
EOF
